-- Add Score Distillation Sampling, introduced in arXiv 2209.14988.
-- Added 2026-10-18 from a scan of methods named by many recent papers but
-- missing from the catalog. The source paper gets the source evidence row (Introduced banner).

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'score-distillation-sampling',
    'Score Distillation Sampling',
    'Score Distillation Sampling (SDS)',
    'Score Distillation Sampling (SDS) is a loss, introduced with DreamFusion, that uses a frozen pretrained 2D text-to-image [diffusion](/methods/diffusion) model as a prior for optimizing any differentiable image generator. A rendering of the parameters is noised, the diffusion model predicts the noise conditioned on a text prompt, and the difference between predicted and injected noise is backpropagated into the generator without differentiating through the diffusion network itself. The authors derive it from probability density distillation, minimizing a KL divergence between Gaussian-noised renderings and the score functions learned by the diffusion model. In DreamFusion, SDS optimizes a randomly initialized [NeRF](/methods/nerf) so that its renderings from random viewpoints look like the prompt, producing text-to-3D objects with no 3D training data and no changes to the image model (Imagen). SDS became the foundation of optimization-based text-to-3D, 3D editing and [Gaussian Splatting](/methods/gaussian-splatting) generation, with refinements such as variational score distillation in [ProlificDreamer](/paper/2305.16213).',
    'score distillation sampling, SDS loss, SDS-based, SDS optimization, SDS guidance',
    (
        SELECT id
        FROM areas
        WHERE name = 'Vision'
        LIMIT 1
    ),
    2022,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2209.14988'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'DreamFusion: Text-to-3D using 2D Diffusion',
    'https://github.com/threestudio-project/threestudio',
    NULL,
    '[DreamFusion: Text-to-3D using 2D Diffusion](/paper/2209.14988)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id FROM methods
WHERE slug = 'score-distillation-sampling' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source' FROM methods
WHERE slug = 'score-distillation-sampling' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

