INSERT INTO paper_method_exclusions (paper_id, method_id, reason)
SELECT paper_id, method_id, 'score-distillation-sampling citation review 2026-10-18: cites the source without naming the method in title or abstract'
FROM score_distillation_sampling_excluded_papers
ON CONFLICT (paper_id, method_id) DO UPDATE SET
    reason = EXCLUDED.reason,
    updated_at = now();

DELETE FROM paper_methods pm
USING score_distillation_sampling_excluded_papers x
WHERE pm.paper_id = x.paper_id AND pm.method_id = x.method_id;

